// synth: lemma: the implementation's expression equals the textbook formula
//         exactly when n is even. This makes explicit why the original
//         postcondition (the textbook formula) does not hold for odd n.
lemma EvenEquality(n: int)
  // tightened to match the call-site precondition; the fact is about nonnegative n
  requires n >= 1
  ensures (n / 2) * (1 + n) == n * (n + 1) / 2 <==> n % 2 == 0
{
  var k := n / 2;
  if n % 2 == 0 {
    // for even n we have n == 2*k, and the algebraic steps are straightforward
    assert n == 2 * k;
    assert (n / 2) * (1 + n) == k * (1 + 2 * k);
    assert n * (n + 1) / 2 == (2 * k) * (2 * k + 1) / 2;
    assert (2 * k) * (2 * k + 1) / 2 == k * (2 * k + 1);
    assert k * (1 + 2 * k) == k * (2 * k + 1);
  } else {
    // for odd n we have n == 2*k + 1, compute both sides and show they differ
    assert n == 2 * k + 1;
    // Left-hand side: (n/2)*(1+n) = k*(1 + (2*k+1)) = k*(2*k+2) = 2*k*(k+1)
    assert (n / 2) * (1 + n) == k * (1 + (2 * k + 1));
    assert k * (1 + (2 * k + 1)) == k * (2 * k + 2);
    assert k * (2 * k + 2) == 2 * k * (k + 1);

    // Right-hand side: n*(n+1)/2 = (2*k+1)*(2*k+2)/2 = (2*k+1)*(k+1)
    assert n * (n + 1) / 2 == (2 * k + 1) * (2 * k + 2) / 2;
    assert (2 * k + 1) * (2 * k + 2) / 2 == (2 * k + 1) * (k + 1);

    // Their difference is (k+1), which is nonzero for n >= 1 (since k >= 0)
    assert (2 * k + 1) * (k + 1) - 2 * k * (k + 1) == k + 1;
    assert k + 1 != 0;
    assert (n / 2) * (1 + n) != n * (n + 1) / 2;
  }
}

