// synth: library theory (phase 0)
// doc: This models Python's math.isqrt(a): given an integer a, it returns the
// doc: nonnegative integer r such that r*r <= a < (r+1)*(r+1). In Python,
// doc: math.isqrt accepts arbitrarily large (unbounded) integers. If a is
// doc: negative, Python raises ValueError; this Dafny method instead requires
// doc: a >= 0 (callers should treat negative input as an error condition).
// doc: The result is the floor of the exact square root, i.e., the largest
// doc: integer r with r*r <= a.
method IntSqrtFloor(a: int) returns (r: nat)
  requires a >= 0
  ensures r * r <= a < (r + 1) * (r + 1)
{
  var lo := 0;
  var hi := a + 1; // hi > sqrt(a) initially
  // loop maintains 0 <= lo <= hi, lo*lo <= a, and hi*hi > a,
  // and shrinks the interval so it terminates.
  while lo + 1 < hi
    invariant 0 <= lo <= hi
    invariant lo * lo <= a
    invariant hi * hi > a
    decreases hi - lo
  {
    var mid := lo + (hi - lo) / 2;
    if mid * mid <= a {
      lo := mid;
    } else {
      hi := mid;
    }
  }
  r := lo;
}

