method rescale_to_unit(numbers: array<real>) returns (return_value: seq<real>)
  // synth: frozen precondition line 1 (from phase 0b)
  requires numbers.Length >= 2
  // synth: frozen precondition line 2 (from phase 0b)
  requires exists i, j :: 0 <= i < j && j < numbers.Length && numbers[i] != numbers[j]
  // synth: postcondition from assert: "assert len(numbers) == len(return_value)"
  ensures numbers.Length == |return_value|
{
  // src: source.py:4 | ma, mi = (max(numbers), min(numbers))
