// synth: lemma that Py_map_float preserves length
// (structural induction over s)
lemma Py_map_float_length(f: real -> real, s: seq<real>)
  ensures |Py_map_float(f, s)| == |s|
{
  if |s| == 0 {
    // trivial
  } else {
    // Py_map_float(f, s) == [f(s[0])] + Py_map_float(f, s[1..])
    Py_map_float_length(f, s[1..]);
    assert |Py_map_float(f, s)| == 1 + |Py_map_float(f, s[1..])|;
    assert 1 + |Py_map_float(f, s[1..])| == 1 + |s[1..]|;
  }
}

