// synth: lemma: Py_max is >= every element (induction)
lemma Py_max_ge_all(s: seq<real>)
  requires |s| > 0
  ensures forall t :: 0 <= t < |s| ==> Py_max(s) >= s[t]
{
  if |s| == 1 {
    // Py_max(s) == s[0], trivial
  } else {
    var tail := s[1..];
    Py_max_ge_all(tail);
    var tailMax := Py_max(tail);
    if s[0] >= tailMax {
      // Py_max(s) == s[0]
      assert Py_max(s) == s[0];
      // for t == 0
      assert Py_max(s) >= s[0];
      // for t >= 1, use induction on tail
      forall t | 1 <= t < |s|
        ensures Py_max(s) >= s[t]
      {
        // t-1 in tail
        assert Py_max(s) >= tail[t-1];
        // tail[t-1] == s[t]
      }
    } else {
      // Py_max(s) == tailMax
      assert Py_max(s) == tailMax;
      // for t == 0
      assert Py_max(s) >= s[0] by {
        // tailMax >= each tail element; we need tailMax >= s[0] from s[0] < tailMax case?
        // Actually here s[0] < tailMax, so tailMax > s[0] and thus tailMax >= s[0]
      }
      // for t >=1 use induction
      forall t | 1 <= t < |s|
        ensures Py_max(s) >= s[t]
      {
        assert Py_max(s) >= tail[t-1];
      }
    }
  }
}

// synth: lemma: Py_min is <= every element (induction)
lemma Py_min_le_all(s: seq<real>)
  requires |s| > 0
  ensures forall t :: 0 <= t < |s| ==> Py_min(s) <= s[t]
{
  if |s| == 1 {
    // trivial
  } else {
    var tail := s[1..];
    Py_min_le_all(tail);
    var tailMin := Py_min(tail);
    if s[0] <= tailMin {
      assert Py_min(s) == s[0];
      assert Py_min(s) <= s[0];
      forall t | 1 <= t < |s|
        ensures Py_min(s) <= s[t]
      {
        assert Py_min(s) <= tail[t-1];
      }
    } else {
      assert Py_min(s) == tailMin;
      assert Py_min(s) <= s[0] by {
        // s[0] > tailMin implies tailMin <= s[0]
      }
      forall t | 1 <= t < |s|
        ensures Py_min(s) <= s[t]
      {
        assert Py_min(s) <= tail[t-1];
      }
    }
  }
}

// synth: lemma: if there are two distinct elements, max != min
lemma MaxNotEqMinWhenDistinct(s: seq<real>)
  requires |s| > 0
  requires exists i, j :: 0 <= i < j && j < |s| && s[i] != s[j]
  ensures Py_max(s) != Py_min(s)
{
  var i :| 0 <= i < |s|;
  var j :| 0 <= j < |s|;
  // pick witnesses from the requires existential
  i, j :| 0 <= i < j && j < |s| && s[i] != s[j];

  if Py_max(s) == Py_min(s) {
    Py_max_ge_all(s);
    Py_min_le_all(s);
    // For any t, Py_max(s) >= s[t] and Py_min(s) <= s[t].
    // If equal, then s[t] == Py_max(s).
    assert s[i] == Py_max(s);
    assert s[j] == Py_max(s);
    assert s[i] == s[j]; // contradicts witness
    assert false;
  }
}

