// Helper lemma: relate indices of Range to arithmetic expression start + k
// synth: lemma to expose the structural property of Range needed by the verifier
lemma Range_index(start: int, end: int, k: int)
  requires 0 <= k < |Range(start, end)|
  ensures  Range(start, end)[k] == start + k
  decreases end - start
{
  if start < end {
    if k == 0 {
      // Range(start,end) == [start] + Range(start+1,end)
      assert Range(start, end)[0] == start;
    } else {
      // relate the tail
      assert Range(start, end)[1..] == Range(start + 1, end);
      Range_index(start + 1, end, k - 1);
      assert Range(start + 1, end)[k - 1] == (start + 1) + (k - 1);
      assert Range(start, end)[k] == start + k;
    }
  } else {
    // start >= end cannot happen because the precondition requires k < |Range(start,end)| = 0
    assert false;
  }
}

