lemma TwoTimesHalfEqualsMinusMod(n: int)
  ensures 2 * (n / 2) == n - n % 2
{
  // standard division-modulus identity: n = 2*(n/2) + n%2
  assert n == 2 * (n / 2) + n % 2;
  assert 2 * (n / 2) == n - n % 2;
}

lemma MinAtLeastMax_from_lengths(n: int)
