  assert ! (|min_values| < |max_values|);
  // unfold the definition of common and conclude equality with |max_values|
  assert common == if |min_values| < |max_values| then |min_values| else |max_values|;
  assert common == |max_values|;
}

// synth: Lemma relating the half-difference to n%2: (n+1)/2 - n/2 == n%2
lemma HalfDiffEqualsMod2(n: int)
  ensures (n + 1) / 2 - n / 2 == n % 2
{
  // reason by cases on n%2
  if n % 2 == 0 {
    // n even: n = 2*(n/2)
    assert n == 2 * (n / 2);
    // then (n+1)/2 == n/2 and difference is 0
    assert (n + 1) / 2 == n / 2;
    assert (n + 1) / 2 - n / 2 == 0;
    assert n % 2 == 0;
  } else {
    // n odd: n = 2*(n/2) + 1
    assert n == 2 * (n / 2) + 1;
    // then (n+1)/2 == n/2 + 1 and difference is 1
    assert (n + 1) / 2 == n / 2 + 1;
    assert (n + 1) / 2 - n / 2 == 1;
    assert n % 2 == 1;
  }
}

