// synth: library theory (phase 0)
module PythonLib {
  // doc: Python has a single singleton value None. It is returned by functions
  // doc: that execute a plain "return" with no expression or that fall off the
  // doc: end without returning. None is a distinct object; comparisons (is / is
  // doc: not) may be used to test identity with None. None carries no numeric
  // doc: semantics and attempting to use it as a number in Python raises a
  // doc: TypeError (not modeled here).
  datatype PyNone = PyNoneValue

  // doc: Python's "/" operator on numeric operands (ints or floats) performs
  // doc: "true division" and returns a float. For the purposes of this model we
  // doc: represent numeric values as Dafny reals. Python raises
  // doc: ZeroDivisionError if the right-hand operand is numerically zero.
  // doc: This function models Python's a / b for numeric a,b and therefore
  // doc: requires the divisor to be nonzero. The result is the real quotient.
  function PyDiv(a: real, b: real): real
    requires b != 0.0
  {
    a / b
  }

  // doc: Python's built-in abs(x) returns the absolute value of a numeric x.
  // doc: For ints it returns an int; for floats it returns a float. Here we
  // doc: model abs on reals. The result is nonnegative and equals x when x>=0,
  // doc: otherwise equals -x. There are no exceptions for numeric inputs.
  function PyAbs(x: real): real
  {
    if x >= 0.0 then x else -x
  }

  // doc: In Python, the truth value testing of a sequence object (list, tuple,
  // doc: etc.) is defined by its length: an empty sequence is False in a boolean
  // doc: context and a non-empty sequence is True. More generally, objects may
  // doc: define __bool__ or __len__; for plain sequences the rule above applies.
  // doc: This function implements that sequence truthiness: returns true iff
  // doc: the sequence has positive length.
  function SeqIsTruthy<T>(s: seq<T>): bool
  {
    |s| != 0
  }

  // doc: Iteration "for x in seq:" over a Python sequence visits elements in
  // doc: index order from 0 to len(seq)-1. The iteration order is stable and
  // doc: deterministic for sequence types: it yields s[0], s[1], ..., s[n-1].
  // doc: This identity function models that ordering by returning the same
  // doc: sequence; a consumer may treat its elements in this order.
  function SeqIterationOrder<T>(s: seq<T>): seq<T>
  {
    s
  }

  // doc: Python dictionaries are mutable mappings from hashable keys to values.
  // doc: The dict subscription operation d[k] (get) returns the value for k if
  // doc: present; otherwise Python raises KeyError. Assignment d[k] = v creates
  // doc: a new entry if k was absent or replaces the existing value if present.
  // doc: Augmented assignment like d[k] += 1 is evaluated as "temp = d[k];
  // doc: temp = temp + 1; d[k] = temp" and hence performs a get followed by a
  // doc: set (and will raise KeyError on the get if k is absent).
  class PyDictStringInt {
    var m: map<string, int>

    // doc: Construct a new Python dict with the given initial contents. The map
    // doc: argument models the mapping of keys to values at construction time.
    constructor(initial: map<string,int>)
      ensures m == initial
    {
      m := initial;
    }

    // doc: Model of Python's d[k] get operation: returns the value associated
    // doc: with key k when k is present in the dict. If k is not present,
    // doc: Python would raise KeyError; this method uses a precondition to
    // doc: reflect that behaviour.
    method Get(k: string) returns (v: int)
      requires k in m
      ensures v == m[k]
    {
      v := m[k];
    }

    // doc: Model of Python's assignment d[k] = v. If the key k is already
    // doc: present its value is replaced; otherwise a new key/value pair is
    // doc: inserted. This method mutates the dict in-place to match Python's
    // doc: dict semantics.
    method Set(k: string, v: int)
      modifies this
      ensures m == old(m)[k := v]
    {
      m := m[k := v];
    }
  }

  // doc: Numeric comparisons between Python ints and floats compare their
  // doc: numeric values; there is implicit coercion so that e.g. 1 < 1.5 is true.
  // doc: For our model (using reals) the standard <, >, == on reals corresponds
  // doc: to Python's numeric comparisons. There are no exceptions raised for
  // doc: ordinary numeric comparisons.
  function PyLess(a: real, b: real): bool
  {
    a < b
  }

  function PyGreater(a: real, b: real): bool
  {
    a > b
  }

  function PyEqualNum(a: real, b: real): bool
  {
    a == b
  }
}

