// synth: lemma: Sum preserves equality of sequences (congruence)
lemma SumCongruent(a: seq<int>, b: seq<int>)
  requires a == b
  ensures Sum(a) == Sum(b)
  decreases |a|
{
  if |a| == 0 {
    // both are empty sequences
