    assert a[0] == b[0];
    assert a[1..] == b[1..];
    assert Sum(a) == a[0] + Sum(a[1..]);
    assert Sum(b) == b[0] + Sum(b[1..]);
    SumCongruent(a[1..], b[1..]);
    assert Sum(a[1..]) == Sum(b[1..]);
    assert Sum(a) == Sum(b);
  }
}

// synth: lemma: Sum of a prefix of length i+1 equals Sum(prefix of length i) + s[i]
lemma SumPrefixAdd(s: seq<int>, i: int)
  requires 0 <= i < |s|
  ensures Sum(s[0..i+1]) == Sum(s[0..i]) + s[i]
  decreases i
{
  if i == 0 {
    // Sum(s[0..1]) == s[0], Sum(s[0..0]) == 0
    assert Sum(s[0..1]) == (s[0..1])[0];
    assert (s[0..1])[0] == s[0];
    assert Sum(s[0..0]) == 0;
  } else {
    // unfold Sum on the two slices to expose their heads and tails
    assert (s[0..i+1])[0] == s[0];
    assert (s[0..i+1])[1..] == s[1..i+1];
    assert Sum(s[0..i+1]) == (s[0..i+1])[0] + Sum((s[0..i+1])[1..]);

    assert (s[0..i])[0] == s[0];
    assert (s[0..i])[1..] == s[1..i];
    assert Sum(s[0..i]) == (s[0..i])[0] + Sum((s[0..i])[1..]);

    // recurse on the tail and the smaller index
    SumPrefixAdd(s[1..], i-1);

    // From the recursive call we obtain:
    // Sum((s[1..])[0..i]) == Sum((s[1..])[0..(i-1)]) + (s[1..])[i-1]
    // Now relate the (s[1..])-slices to the corresponding s-slices so we can conclude the goal.
    assert (s[1..])[0..i] == s[1..i+1];
    assert (s[1..])[0..(i-1)] == s[1..i];
    assert (s[1..])[i-1] == s[i];

