    SumCongruent((s[1..])[0..i], s[1..i+1]);
    SumCongruent((s[1..])[0..(i-1)], s[1..i]);

    // now rewrite the recursive equation into the desired form
    assert Sum((s[1..])[0..i]) == Sum((s[1..])[0..(i-1)]) + (s[1..])[i-1];
    assert Sum(s[1..i+1]) == Sum(s[1..i]) + s[i];

    // Use congruence lemma to move equality from sequences to their sums
    SumCongruent((s[0..i+1])[1..], s[1..i+1]);
    SumCongruent((s[0..i])[1..], s[1..i]);

    // convert those equalities to the corresponding sliced sums
    assert Sum((s[0..i+1])[1..]) == Sum(s[1..i+1]);
    assert Sum((s[0..i])[1..]) == Sum(s[1..i]);
    assert Sum((s[0..i+1])[1..]) == Sum((s[0..i])[1..]) + s[i];

    // combine the equalities
    assert Sum(s[0..i+1]) == s[0] + Sum((s[0..i+1])[1..]);
    assert Sum(s[0..i]) == s[0] + Sum((s[0..i])[1..]);
    assert Sum(s[0..i+1]) == Sum(s[0..i]) + s[i];
  }
}
