      assert SumParity(s, p) == (if p == 1 && s[0] % 2 == 1 then s[0] else 0) + SumParity(tail, 1 - p);
      // Apply induction to tail with k-1 and parity 1-p (note 0 <= k-1 <= |tail|)
      assert 0 <= k - 1 <= |tail|;
      SumParity_Split(tail, k - 1, 1 - p);
      // From the induction hypothesis:
      // SumParity(tail,1-p) == SumParity(tail[..k-1],1-p) + SumParity(tail[k-1..], (1-p + (k-1)) % 2)
      assert SumParity(tail, 1 - p) == SumParity(tail[..k - 1], 1 - p) + SumParity(tail[k - 1..], (1 - p + (k - 1)) % 2);
      // Show the parity arithmetic aligns: (1-p + (k-1)) % 2 == (p + k) % 2
      assert (1 - p + (k - 1)) % 2 == (p + k) % 2;

      // Relate s[..k] to its head and the appropriate tail slice so we can expand SumParity(s[..k],p)
      // (s[..k])[0] == s[0]
      assert (s[..k])[0] == s[0];
      // (s[..k])[1..] == tail[..k-1]
      assert (s[..k])[1..] == tail[..k - 1];
      // Expand SumParity on s[..k] by definition and substitute the equalities above
      assert SumParity(s[..k], p)
