      // And:
      // SumParity(s[k..], (p + k) % 2) == SumParity(tail[k-1..], (1-p + (k-1)) % 2)
      assert SumParity(s[k..], (p + k) % 2) == SumParity(tail[k - 1..], (1 - p + (k - 1)) % 2);
