// synth: lemma showing that when the tail has length 1 or 2 and starting parity is 1,
// the SumParity of that tail equals the contribution of its first element only.
lemma SumParity_ShortTailHeadOnly(t: seq<int>)
  requires 1 <= |t| <= 2
  ensures SumParity(t, 1) == (if t[0] % 2 == 1 then t[0] else 0)
{
  if |t| == 1 {
    // By definition
    assert SumParity(t, 1) == (if 1 == 1 && t[0] % 2 == 1 then t[0] else 0) + SumParity(t[1..], 0);
    // t[1..] is empty so its SumParity is 0
    assert SumParity(t[1..], 0) == 0;
    assert SumParity(t, 1) == (if t[0] % 2 == 1 then t[0] else 0);
  } else {
    // |t| == 2
    // SumParity(t,1) == (if t[0] odd then t[0] else 0) + SumParity(t[1..], 0)
    // but SumParity(t[1..], 0) with a single element and parity 0 does not include that element
    assert SumParity(t, 1) == (if t[0] % 2 == 1 then t[0] else 0) + SumParity(t[1..], 0);
    assert SumParity(t[1..], 0) == 0;
    assert SumParity(t, 1) == (if t[0] % 2 == 1 then t[0] else 0);
  }
}

// synth: lemma to show SumParity on a full slice equals SumParity on the sequence itself
lemma SumParity_FullSlice(s: seq<int>, p: int)
  requires p == 0 || p == 1
  ensures SumParity(s[..|s|], p) == SumParity(s, p)
  decreases |s|
{
  if |s| == 0 {
    // both sides are 0
  } else {
    var tail := s[1..];
    // expand SumParity on the full slice and on s, and relate their components
    assert SumParity(s[..|s|], p) == (if p == 1 && (s[..|s|])[0] % 2 == 1 then (s[..|s|])[0] else 0) + SumParity((s[..|s|])[1..], 1 - p);
    assert (s[..|s|])[0] == s[0];
    assert (s[..|s|])[1..] == tail;
    assert SumParity(s, p) == (if p == 1 && s[0] % 2 == 1 then s[0] else 0) + SumParity(tail, 1 - p);
    // now both SumParity(s[..|s|], p) and SumParity(s, p) are equal to the same expression, so they are equal
    assert SumParity(s[..|s|], p) == (if p == 1 && s[0] % 2 == 1 then s[0] else 0) + SumParity(tail, 1 - p);
  }
}

