  ensures CountRange(n) - IterDone(i) >= 1
{
  // By induction on n (decreasing) together with reducing i by 3 when needed.
  if n < 2 {
    // impossible given i >= 2 and i <= n
    assert false;
  } else if n < 3 {
    // n == 2
    // then i must be 2
    assert n == 2;
    assert i == 2;
    assert CountRange(n) == 1;
    assert IterDone(i) == 0;
    assert CountRange(n) - IterDone(i) == 1;
  } else {
    // n >= 3
    if i == 2 {
      // then IterDone(i) == 0, and CountRange(n) >= 1
      assert IterDone(i) == 0;
      // use CountRange decomposition: CountRange(n) == 1 + CountRange(n-3) >= 1
      assert CountRange(n) == 1 + CountRange(n - 3);
      assert CountRange(n) >= 1;
    } else {
      // i >= 5 and both i and n can be reduced by 3
      // reduce goal to smaller n and i
      // Need to ensure i-3 <= n-3
      assert 2 <= i - 3 && (i - 3) % 3 == 2;
      assert i - 3 <= n - 3;
      IterDone_lt_CountRange(n - 3, i - 3);
      // unfold recursive definitions
      assert CountRange(n) == 1 + CountRange(n - 3);
      assert IterDone(i) == 1 + IterDone(i - 3);
      // from IH: CountRange(n-3) - IterDone(i-3) >= 1
      assert CountRange(n - 3) - IterDone(i - 3) >= 1;
      assert CountRange(n) - IterDone(i) == CountRange(n - 3) - IterDone(i - 3);
    }
  }
}

// synth: small arithmetic lemma: CountRange(n) is non-negative
lemma CountRange_nonneg(n: int)
  decreases n
  ensures CountRange(n) >= 0
{
  if n < 2 {
    assert CountRange(n) == 0;
  } else {
    assert CountRange(n) == 1 + CountRange(n - 3);
    CountRange_nonneg(n - 3);
    assert CountRange(n - 3) >= 0;
    assert CountRange(n) >= 0;
  }
}

