theory:
// synth: library theory (phase 0)
// doc: Return the absolute value of integer n as a Dafny nat (non-negative integer).
// doc: This models Python's abs(n) when used on integers in contexts where a non-negative
// doc: integer is required. It is total for all int inputs and never fails.
function abs_nat(n: int): nat {
  if n >= 0 then n else -n
}

// doc: Return the base-10 digits of a non-negative integer n as a sequence of ints.
// doc: The sequence contains one element per decimal digit, in most-significant-first order.
// doc: For n == 0, the result is [0]. For n > 0, the first digit is non-zero (no leading zeros).
// doc: Each element of the result is in 0..9. This is a pure, total function for all nat inputs.
// doc: It uses the usual Euclidean decimal decomposition: n = 10*q + r with r in 0..9.
function digits_nat(n: nat): seq<int>
  decreases n
{
  if n == 0 then [0]
  else if n < 10 then [n]
  else digits_nat(n / 10) + [n % 10]
}

// doc: Return the sequence of Unicode code points (as ints) that are the ASCII decimal
// doc: representation of the integer n, exactly as Python's str(n) would produce for integers.
// doc: For n < 0 the sequence begins with 45 (U+002D, the '-' character) followed by the
// doc: decimal digit characters U+0030..U+0039. For n >= 0 the sequence contains only the
// doc: digit characters. For 0 the result is the single-element sequence [48] (the character '0').
// doc: This is total for all int inputs and does not raise exceptions.
function py_str_of_int(n: int): seq<int>
{
  var ds := digits_nat(abs_nat(n));
  var chars := digits_to_chars(ds);
  if n < 0 then [45] + chars else chars
}

// doc: Convert a sequence of decimal digits (each in 0..9) to the sequence of Unicode code points
// doc: for the corresponding ASCII digit characters (U+0030 .. U+0039), preserving order.
// doc: The input may be empty (resulting in empty sequence); typically it is non-empty when used
// doc: with digits_nat. This function is total and purely functional.
function digits_to_chars(ds: seq<int>): seq<int>
  decreases |ds|
{
  if |ds| == 0 then []
  else digits_to_chars(ds[..|ds|-1]) + [48 + ds[|ds|-1]]
}

