// ---------------------------------------------------------------------------
// Lemmas to help the verifier:
//
// - DigitsNat_props: digits_nat produces at least one digit and each digit is in 0..9.
// - DigitsToChars_props: digits_to_chars preserves length and maps each digit d to 48+d.
// - CountDigits: counts how many elements of a sequence are ASCII digit characters (48..57).
// - CountDigits_digits_to_chars: for any digit-sequence ds, digits_to_chars(ds) has exactly |ds| digits.
// - CountDigits_concat: CountDigits distributes over concatenation.
// - CountDigitsEqualsAbsLen: the number of ASCII digit characters in py_str_of_int(n)
//   equals the length of py_str_of_int(abs_nat(n)) (i.e. the digits-only length).
// ---------------------------------------------------------------------------

// synth: introduce CountDigits function to avoid set-comprehension syntax issues
function CountDigits(s: seq<int>): nat
  decreases |s|
{
  if |s| == 0 then 0
  else CountDigits(s[..|s|-1]) + (if 48 <= s[|s|-1] <= 57 then 1 else 0)
}

lemma DigitsNat_props(n: nat)
  ensures |digits_nat(n)| >= 1
  ensures forall k :: 0 <= k < |digits_nat(n)| ==> 0 <= digits_nat(n)[k] <= 9
  decreases n
{
  if n == 0 {
    // digits_nat(0) == [0]
    assert digits_nat(0) == [0];
    assert |digits_nat(0)| == 1;
    assert digits_nat(0)[0] == 0;
  } else if n < 10 {
    // digits_nat(n) == [n] with 0 <= n <= 9
    assert digits_nat(n) == [n];
    assert |digits_nat(n)| == 1;
    assert 0 <= n <= 9;
  } else {
    // n >= 10
    var q := n / 10;
    var r := n % 10;
    DigitsNat_props(q);
    assert digits_nat(n) == digits_nat(q) + [r];
    // length
    assert |digits_nat(n)| == |digits_nat(q)| + 1;
    assert |digits_nat(q)| >= 1; // from inductive hypothesis

    // The prefix of digits_nat(n) of length |digits_nat(q)| equals digits_nat(q)
    assert digits_nat(n)[..|digits_nat(q)|] == digits_nat(q);
    // From the inductive hypothesis on q we get element bounds for the prefix
    assert forall k :: 0 <= k < |digits_nat(q)| ==> 0 <= digits_nat(n)[k] <= 9;

    // bound for last digit r
    assert 0 <= r <= 9;
    // last element equals r
    assert digits_nat(n)[|digits_nat(q)|] == r;

    // combine prefix and last-element facts to cover all indices
    assert forall k :: 0 <= k < |digits_nat(n)| ==> 0 <= digits_nat(n)[k] <= 9;
  }
}

lemma DigitsToChars_props(ds: seq<int>)
  ensures |digits_to_chars(ds)| == |ds|
  ensures forall k :: 0 <= k < |ds| ==> digits_to_chars(ds)[k] == 48 + ds[k]
  decreases |ds|
{
  if |ds| == 0 {
    assert digits_to_chars(ds) == [];
    assert |digits_to_chars(ds)| == 0;
  } else {
    var n := |ds|;
    var prefix := ds[..n-1];
    DigitsToChars_props(prefix);
    assert digits_to_chars(ds) == digits_to_chars(prefix) + [48 + ds[n-1]];
    assert |digits_to_chars(ds)| == |digits_to_chars(prefix)| + 1;
    assert |digits_to_chars(prefix)| == |prefix|;
    assert |digits_to_chars(ds)| == |prefix| + 1 == |ds|;

    // prefix equality and known mapping on prefix
    assert digits_to_chars(ds)[..|prefix|] == digits_to_chars(prefix);
    assert forall k :: 0 <= k < |prefix| ==> digits_to_chars(ds)[k] == 48 + ds[k];
    // last element mapping
    assert digits_to_chars(ds)[|prefix|] == 48 + ds[n-1];

    // combine to full element-wise equality
    assert forall k :: 0 <= k < |ds| ==> digits_to_chars(ds)[k] == 48 + ds[k];
  }
}

// synth: sequence concatenation properties needed by CountDigits_concat and other proofs
lemma SeqConcatLast(a: seq<int>, b: seq<int>)
  requires |b| > 0
  ensures |a + b| == |a| + |b|
  ensures (a + b)[|a + b|-1] == b[|b|-1]
  ensures (a + b)[..|a + b|-1] == a + b[..|b|-1]
  decreases |b|
{
  if |b| == 1 {
    // b == [b[0]]
    assert a + b == a + [b[0]];
    assert |a + b| == |a| + 1;
    assert (a + b)[|a + b|-1] == b[0];
    assert (a + b)[..|a + b|-1] == a;
  } else {
    var n := |b|;
    var bprefix := b[..n-1];
    SeqConcatLast(a, bprefix);
    // associative unfolding: a + b == (a + bprefix) + [b[n-1]]
    assert a + b == (a + bprefix) + [b[n-1]];
    // lengths
    assert |a + b| == |a + bprefix| + 1;
    assert |a + bprefix| == |a| + |bprefix|;
    assert |a + b| == |a| + |bprefix| + 1;
    assert |a + b| == |a| + |b|;

    // last element is b[n-1]
    assert (a + b)[|a + b|-1] == b[n-1];

    // prefix equals (a + bprefix) which equals a + b[..n-1]
    assert (a + b)[..|a + b|-1] == a + bprefix;
    assert bprefix == b[..n-1];
    assert (a + b)[..|a + b|-1] == a + b[..n-1];
  }
}

// synth: CountDigits distributes over concatenation
lemma CountDigits_concat(a: seq<int>, b: seq<int>)
  ensures CountDigits(a + b) == CountDigits(a) + CountDigits(b)
  decreases |b|
{
  if |b| == 0 {
    assert a + b == a;
    assert CountDigits(a + b) == CountDigits(a);
  } else {
    var n := |b|;
    var bprefix := b[..n-1];
    // apply inductive hypothesis to a and bprefix
    CountDigits_concat(a, bprefix);
    // justify splitting the last element of a+b using sequence concatenation properties
    SeqConcatLast(a, b); // ensures (a+b) == (a+bprefix) + [b[n-1]] and length facts
    // expand definitions for CountDigits on concatenation
    assert CountDigits(a + b) == CountDigits((a + bprefix) + [b[n-1]]);
    assert CountDigits(a + b) == CountDigits(a + bprefix) + (if 48 <= b[n-1] <= 57 then 1 else 0);
    assert CountDigits(b) == CountDigits(bprefix) + (if 48 <= b[n-1] <= 57 then 1 else 0);
    // use IH
    assert CountDigits(a + bprefix) == CountDigits(a) + CountDigits(bprefix);
    // combine
    assert CountDigits(a + b) == CountDigits(a) + CountDigits(b);
  }
}

// synth: CountDigits of digits_to_chars(ds) equals |ds|
// Require that ds actually contains digits 0..9 so the conditional in the proof is decidable.
lemma CountDigits_digits_to_chars(ds: seq<int>)
  requires forall k :: 0 <= k < |ds| ==> 0 <= ds[k] <= 9
  ensures CountDigits(digits_to_chars(ds)) == |ds|
  decreases |ds|
{
  if |ds| == 0 {
    assert digits_to_chars(ds) == [];
    assert CountDigits(digits_to_chars(ds)) == 0;
  } else {
    var n := |ds|;
    var prefix := ds[..n-1];
    // From the requires for ds we get the same property for prefix
    assert forall k :: 0 <= k < |prefix| ==> 0 <= prefix[k] <= 9;
    // Apply IH to prefix
    CountDigits_digits_to_chars(prefix);
    assert digits_to_chars(ds) == digits_to_chars(prefix) + [48 + ds[n-1]];
    // Expand CountDigits on the concatenation
    CountDigits_concat(digits_to_chars(prefix), [48 + ds[n-1]]);
    assert CountDigits(digits_to_chars(ds)) == CountDigits(digits_to_chars(prefix)) + (if 48 <= 48 + ds[n-1] <= 57 then 1 else 0);
    // Use IH on prefix to replace CountDigits(digits_to_chars(prefix)) with |prefix|
    assert CountDigits(digits_to_chars(prefix)) == |prefix|;
    // Use digit bound for ds[n-1] (from requires) to show the conditional equals 1
    assert 0 <= ds[n-1] <= 9;
    assert 48 <= 48 + ds[n-1] <= 57;
    assert (if 48 <= 48 + ds[n-1] <= 57 then 1 else 0) == 1;
    // combine to get final equality
    assert CountDigits(digits_to_chars(ds)) == |prefix| + 1;
    assert |prefix| + 1 == |ds|;
