    assert PySum(s[..0]) == 0;
  } else {
    // establish bounds for the recursive call on the tail
    assert 0 < i < |s|;
    assert 0 <= i - 1;
    assert i - 1 < |s| - 1;
    assert 0 <= i - 1 < |s[1..]|;

    // relate the slices to the tail-of-tail form the induction expects
    assert s[1..i+1] == (s[1..])[..i];
    assert s[1..i] == (s[1..])[..i-1];
    assert s[i] == (s[1..])[i-1];

