// synth: library theory (phase 0)
// doc: Python's built-in len(obj) returns the number of items in a sequence-like
// doc: object (for example list or tuple). For a sequence modeled here as a Dafny
// doc: seq<T>, len returns a non-negative integer equal to the sequence length.
// doc: In real Python, calling len() on an object that does not support the
// doc: length protocol raises a TypeError; this model only covers sequence-like
// doc: values and returns their length.
function Len<T>(s: seq<T>): nat
{
  |s|
}

// doc: Python sequence indexing semantics: for a sequence s, the valid index
// doc: range is -len(s) .. len(s)-1 inclusive. A negative index i is interpreted
// doc: as len(s) + i. Accessing an index outside that range raises IndexError in
// doc: Python. This function models that behavior for Dafny seq<T> and requires
// doc: the index to be in the valid Python range; it returns the element at that
// doc: (possibly wrapped) index.
function PyGet<T>(s: seq<T>, i: int): T
  requires -|s| <= i < |s|
{
  if i >= 0 then s[i] else s[|s| + i]
}

// doc: Python's built-in range(start, stop, step) produces an iterable sequence
// doc: of integers beginning at start and repeatedly adding step until the next
// doc: value would be >= stop (if step > 0) or <= stop (if step < 0). The stop
// doc: bound is exclusive. If step == 0, Python raises ValueError. This method
// doc: models range(start, stop, step) as a concrete Dafny sequence seq<int> and
// doc: therefore requires step != 0. The returned sequence lists the values in
// doc: the same order Python's range would yield them.
method PyRange(start: int, stop: int, step: int) returns (res: seq<int>)
  requires step != 0
{
  var cur := start;
  var s: seq<int> := [];
  if step > 0 {
    while cur < stop {
      s := s + [cur];
      cur := cur + step;
    }
  } else {
    // step < 0
    while cur > stop {
      s := s + [cur];
      cur := cur + step;
    }
  }
  res := s;
}

