        // but s[idx] is in s1 (since idx >= 1), so PyCount(s1, s[0]) >= 1, contradiction.
        assert 0 < idx;
        assert s1[idx-1] == s[idx];
        // from the equality at index idx-1 in s1 we can deduce PyCount(s1, s[0]) > 0
        PyCountAtIndexImpliesPositive(s1, s[0], idx - 1);
        assert PyCount(s1, s[0]) > 0;
        // but from the requires with j = 0 we have PyCount(s1, s[0]) == 0
        assert PyCount(s1, s[0]) == 0;
        // contradiction; the branch is impossible under preconditions, so nothing further to prove here
        assert false;
      } else {
        // Now s[0] != s[idx], so PyRemoveFirst(s, s[idx]) == [s[0]] + PyRemoveFirst(s1, s[idx])
        assert PyRemoveFirst(s, s[idx]) == [s[0]] + PyRemoveFirst(s1, s[idx]);
        assert |PyRemoveFirst(s, s[idx])| == 1 + |PyRemoveFirst(s1, s[idx])|;

        // We must show property for all j < idx.
        // Case j == 0:
        //   need PyCount(PyRemoveFirst(s1, s[idx]), s[0]) == 0
        // From precondition with j = 0: PyCount(s1, s[0]) == 0
        assert PyCount(s1, s[0]) == 0;
        // removing the first occurrence of s[idx] from s1 cannot introduce s[0] occurrences
        PyRemoveFirstDoesNotIntroduceNewOccurrences(s1, s[idx], s[0]);
        assert PyCount(PyRemoveFirst(s1, s[idx]), s[0]) == 0;

        // Case j >= 1:
        // For j in 1..idx-1, map to j' = j-1 which is < idx-1.
        // From the requires on s we have for all j' < idx-1 that PyCount(s1[j'+1..], s1[j']) == 0,
        // so we can apply induction on s1 with idx-1.
