        // We show the universal property explicitly for the verifier by splitting j==0 and j>=1.
        assert forall j :: 0 <= j < idx && j < |PyRemoveFirst(s, s[idx])| ==>
          (if j == 0 then PyCount(PyRemoveFirst(s, s[idx])[j+1..], PyRemoveFirst(s, s[idx])[j]) == 0
