    assert s[0] == v;
    assert PyCount(s, v) >= 1;
  } else {
    // reduce to tail
    var s1 := s[1..];
    assert 0 <= k - 1 < |s1|;
    assert s1[k - 1] == v;
    PyCountAtIndexImpliesPositive(s1, v, k - 1);
    // now reconstruct PyCount(s,v)
    if s[0] == v {
      assert PyCount(s, v) >= 1;
    } else {
      assert PyCount(s, v) == PyCount(s1, v);
