    // idx > 0
    var s1 := s[1..];
    PyCountSuffixLeqTotal(s1, idx - 1, v);
    if s[0] == v {
      assert PyCount(s, v) == 1 + PyCount(s1, v);
    } else {
      assert PyCount(s, v) == PyCount(s1, v);
    }
    assert PyCount(s[idx..], v) == PyCount(s1[(idx - 1)..], v);
    // by IH PyCount(s1[(idx-1)..], v) <= PyCount(s1, v)
    assert PyCount(s[idx..], v) <= PyCount(s, v);
  }
}

