// synth: library theory (phase 0)
// doc: A model of Python's built-in list type for use in specifications.
// doc: A PyList<T> wraps a Dafny seq<T> and models the Python list's ordered
// doc: sequence of elements. This model captures the list's element order and
// doc: length. It does not model object identity, aliasing, or in-place
// doc: mutation semantics (mutations are not represented by changing the
// doc: PyList value; instead the model uses different PyList values to represent
// doc: different contents). No Python exceptions are raised by constructing a PyList.
datatype PyList<T> = PyList(contents: seq<T>)

// doc: The length of a Python list. This corresponds to Python's built-in
// doc: len(list). It returns a non-negative integer equal to the number of
// doc: elements in the list. There are no exceptions for well-formed PyList values.
function Len<T>(l: PyList<T>): nat
{
  |l.contents|
}

// doc: Truth testing for Python lists: a Python list is considered False in a
