theory:
// synth: library theory (phase 0)
// doc: Models Python's membership test "x in s" for sequence types.
// doc: Returns true iff there exists an index i with 0 <= i < |s| and s[i] == x.
// doc: Python evaluates membership by testing equality (the object's __eq__ / rich comparison),
// doc: which in Python can run arbitrary code and may raise exceptions; this model treats
// doc: equality as a (pure) decidable relation and does not model Python-side exceptions.
// doc: The function is total on its domain (all sequences and values) and returns a boolean.
function SeqContains<T(==)>(s: seq<T>, x: T): bool
{
  exists i :: 0 <= i < |s| && s[i] == x
}

// doc: Models Python's list.index(x) behavior restricted to the successful case.
// doc: Returns the smallest index i such that s[i] == x. In Python, list.index raises
// doc: ValueError if x is not present; this method requires presence of x (precondition),
// doc: and therefore does not model the exception. Equality is Python's equality semantics;
// doc: here it is modeled as Dafny equality on types that support equality (T(==)).
// doc: The method terminates (decreases measure provided) and ensures the returned index
// doc: satisfies 0 <= i < |s| and s[i] == x.
method IndexOf<T(==)>(s: seq<T>, x: T) returns (i: int)
  requires SeqContains(s, x)
  ensures 0 <= i < |s| && s[i] == x
{
  var j := 0;
  while j < |s|
    invariant 0 <= j <= |s|
    decreases |s| - j
  {
    if s[j] == x {
      i := j;
      return;
    }
    j := j + 1;
  }
  assert false;
}

