// synth: library theory (phase 0)
// doc: Python's right-shift by 1 (the ">> 1" operator on ints) performs an
// doc: arithmetic right shift, which for integers is equal to floor(n / 2).
// doc: For every integer n it returns the unique integer q such that
// doc:   2*q <= n < 2*(q + 1).
// doc: This operation is total on Python ints and does not raise exceptions.
function py_rshift1(n: int): int
{
  // Implementation that yields floor(n/2) for all integers n.
  // For nonnegative n this is the usual truncating division n / 2.
  // For negative n, the formula -(((-n) + 1) / 2) produces floor(n/2).
  if n >= 0 then n / 2 else -(((-n) + 1) / 2)
}

// doc: Python's bitwise-and with 1 (n & 1) returns the least-significant
// doc: bit of n, i.e. 0 if n is even and 1 if n is odd. For Python's
// doc: unbounded two's-complement integers this yields either 0 or 1 for
// doc: every integer n (including negatives). It is total and raises no
// doc: exceptions.
// doc: The value satisfies n == 2 * py_rshift1(n) + py_and1(n) and py_and1(n) ∈ {0,1}.
function py_and1(n: int): int
{
  // Define as the remainder when removing the doubled py_rshift1 part.
  n - 2 * py_rshift1(n)
}

