// synth: library theory (phase 0)
// doc: Python strings (str) are sequences of Unicode code points.  In this
// doc: model a Python string as a Dafny sequence of integers, where each
// doc: integer is a Unicode code point.  The Python semantics relevant here:
// doc: - len(s) is the number of code points.
// doc: - Indexing s[i] (for a Python string) yields a Python string of length 1
// doc:   consisting of the single code point at position i.  (This model
// doc:   represents that single-character Python string as a seq<int> of
// doc:   length 1.)
// doc: - Concatenation of Python strings is the concatenation of the
// doc:   corresponding sequences of code points.
// doc: - Python strings are immutable; this model does not provide mutation.
// doc: This is a modeling choice to permit specifying the behaviour of
// doc: operations used by the program; it is not intended to be a complete
// doc: formalisation of all Python str corner cases.
type PyString = seq<int>

// doc: Python built-in function ord(c):
// doc: - When c is a Python string of length exactly 1, ord(c) returns the
// doc:   integer Unicode code point of that single character.
// doc: - If c is not of length 1, Python raises a TypeError.
// doc: In this model the function requires the caller to provide a PyString
// doc: of length 1 and returns its sole code point.
function py_ord(c: PyString): int
  requires |c| == 1
{
  c[0]
}

// doc: Python str.split() with no separator argument:
// doc: - When called without an explicit separator, Python splits the string
// doc:   on runs of consecutive whitespace characters.  "Whitespace"
// doc:   means characters having the Unicode White_Space property.
// doc: - Leading and trailing whitespace are ignored: sequences of whitespace at
// doc:   either end do not produce empty tokens.
// doc: - The result is a list (modeled here as a sequence) of substrings
// doc:   (each a Python string) that are the maximal non-empty segments of the
// doc:   original string that contain no whitespace.
// doc: - The empty string yields an empty list ([]).  A string consisting only
// doc:   of whitespace yields an empty list.
// doc: - The operation never inserts empty strings into the result (unless a
// doc:   non-default separator is used, which is not the case modeled here).
// doc: - No exceptions are raised by the behaviour described above.
// doc: Note: this declaration is an abstract (uninterpreted) model of Python's
// doc: split-without-sep behaviour; it captures the observable splitting result
// doc: but does not attempt to axiomatise the full Unicode White_Space set here.
function py_split(s: PyString): seq<PyString>

// doc: Python built-in sorted(iterable, *, key=None) as used here:
// doc: - sorted(iterable, key=keyfunc) returns a new list containing the same
// doc:   elements as the iterable, in non-decreasing order according to the
// doc:   values produced by keyfunc(element).  The iterable is traversed from
// doc:   left to right to obtain elements for sorting.
// doc: - Sorting is stable: if two elements compare equal according to their
// doc:   key values, their relative order in the output is the same as in the
// doc:   input traversal order.
// doc: - In Python the key function may return arbitrary values; comparisons
// doc:   between key values use the usual < relation for those values and can
// doc:   raise TypeError if the key values are not comparable.  In this model
// doc:   we restrict the key function to return int (Unicode code points or
// doc:   integers derived from them) so that comparisons are well-defined.
// doc: - The result is a finite sequence (Python list) of the same multiset of
// doc:   elements as the input iterable (i.e., it is a permutation of the
// doc:   elements seen in traversal).
// doc: - This declaration is an abstract specification: it describes the
// doc:   essential properties (permutation + stability + ordering by key)
// doc:   needed by client code rather than giving an implementation.
function py_sorted<T>(items: seq<T>, key: (T) -> int): seq<T>

// doc: Python str.join(iterable_of_strs):
// doc: - Returns the string which is the concatenation of the strings in the
// doc:   iterable, with the separator string (the receiver) inserted between
// doc:   elements.  For example, sep.join([a,b,c]) -> a + sep + b + sep + c.
// doc: - If the iterable is empty the result is the empty string.
// doc: - If any element of the iterable is not a string, Python raises TypeError.
// doc: - This model uses PyString for all strings, so the type enforces the
// doc:   "all elements are strings" requirement; the function implements the
// doc:   concatenation semantics precisely.
// doc: - The implementation below is a total recursive pure function and
// doc:   decreases on the length of the items sequence.
function py_join(sep: PyString, items: seq<PyString>): PyString
  decreases |items|
{
  if |items| == 0 then
    // empty sequence of strings -> empty string
    []
  else if |items| == 1 then
    items[0]
  else
    // items[0] ^ sep ^ join(sep, items[1..])
    items[0] + sep + py_join(sep, items[1..])
}

