theory:
// synth: library theory (phase 0)
// doc: Models the Python idiom of testing a predicate on every element of a sequence.
// doc: Given a sequence s and a predicate pred, returns True iff for every index i
// doc: with 0 <= i < |s|, pred(s[i]) is True. For an empty sequence, Python's all
// doc: semantics (and this function) yield True. This function does not raise any
// doc: exceptions; it is purely a logical characterization of Python's behavior.
function PyAll<T>(s: seq<T>, pred: (T) -> bool): bool
{
  (|s| == 0) || (forall i :: 0 <= i < |s| ==> pred(s[i]))
}

// doc: Models Python's min(a, b) for two integer arguments.
// doc: Returns a if a <= b, otherwise returns b. This matches Python's behavior
// doc: of returning the first argument when the two compare as equal. No exceptions
// doc: are raised by calling min with two integers.
function PyMinTwo(a: int, b: int): int
{
  if a <= b then a else b
}

// doc: Models Python's min(seq) when the argument is a non-empty sequence of ints.
// doc: Returns the smallest integer in the sequence according to the usual numeric
// doc: ordering. If the sequence is empty, Python raises ValueError; to mirror that
// doc: in Dafny this function has a precondition that the sequence is non-empty.
// doc: The function is defined recursively by comparing the head with the minimum
// doc: of the tail and decreases on the length of the sequence to ensure termination.
function PyMinSeq(s: seq<int>): int
  requires |s| > 0
  decreases |s|
{
  if |s| == 1 then s[0] else PyMinTwo(s[0], PyMinSeq(s[1..]))
}

